//! GPU particles for VFX Graph (Unity's Visual Effect Graph): each system keeps its
//! particles in a storage buffer, spawned and updated by compute shaders and drawn as
//! billboards straight from the buffer.
//!
//! A system's behaviour comes from three hooks generated by `oxide_vfx`
//! (`vfx_init`, `vfx_update`, `vfx_output`), wrapped here with the particle layout and the
//! entry points. Free particles sit on a stack of dead indices; spawning pops from it with
//! an atomic counter and dying particles push back.
//! Reference: <https://docs.unity3d.com/Packages/com.unity.visualeffectgraph@17.0/manual/index.html>

use crate::frame::{RenderFrame, VfxBlend, VfxDraw, VfxOrient};
use crate::gpu_assets::GpuAssets;
use crate::renderer::{DEPTH_FORMAT, HDR_FORMAT, validate_wgsl};
use oxide_assets::{AssetId, AssetServer};
use std::collections::HashMap;
use wgpu::util::DeviceExt;

/// Bytes per particle (see `Particle` in the templates).
pub const PARTICLE_SIZE: u64 = 64;
/// Property slots (vec4) of a system.
pub const PROPERTY_SLOTS: usize = 64;
const WORKGROUP: u32 = 64;

/// Declarations shared by the compute and render templates.
pub const PARTICLE_DECLS: &str = "
struct Particle {
    position: vec3f,
    age: f32,
    velocity: vec3f,
    lifetime: f32,
    color: vec3f,
    alpha: f32,
    size: f32,
    angle: f32,
    tex_index: f32,
    alive: u32,
    seed: u32,
    id: u32,
    mass: f32,
    scale_y: f32,
};

struct Sim {
    object_to_world: mat4x4f,
    world_to_object: mat4x4f,
    params: vec4f,      // time, delta time, spawn count, capacity
    seeds: vec4u,       // frame seed, particles spawned before this frame
};

fn vfx_time() -> f32 {
    return sim.params.x;
}

fn vfx_dt() -> f32 {
    return sim.params.y;
}

fn vfx_hash(v: u32) -> u32 {
    let s = v * 747796405u + 2891336453u;
    let w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
    return (w >> 22u) ^ w;
}

// A random number in [0, 1) from a particle's seed and a per-use salt.
fn vfx_rand(seed: u32, salt: u32) -> f32 {
    return f32(vfx_hash(seed ^ vfx_hash(salt)) >> 8u) / 16777216.0;
}
";

const COMPUTE_TEMPLATE: &str = "
@group(0) @binding(0) var<storage, read_write> particles: array<Particle>;
@group(0) @binding(1) var<storage, read_write> dead: array<u32>;
@group(0) @binding(2) var<storage, read_write> counters: array<atomic<i32>, 4>;
@group(0) @binding(3) var<uniform> sim: Sim;
@group(0) @binding(4) var<uniform> props: array<vec4f, 64>;
@group(0) @binding(5) var<storage, read> luts: array<vec4f>;

fn vfx_view_matrix() -> mat4x4f {
    return mat4x4f(vec4f(1.0, 0.0, 0.0, 0.0), vec4f(0.0, 1.0, 0.0, 0.0), vec4f(0.0, 0.0, 1.0, 0.0), vec4f(0.0, 0.0, 0.0, 1.0));
}

fn vfx_camera_pos() -> vec3f {
    return vec3f(0.0);
}

//#HOOKS

@compute @workgroup_size(64)
fn cs_reset(@builtin(global_invocation_id) g: vec3u) {
    let cap = u32(sim.params.w);
    if (g.x < cap) {
        particles[g.x].alive = 0u;
        dead[g.x] = cap - 1u - g.x;
    }
    if (g.x == 0u) {
        atomicStore(&counters[0], i32(cap));
        atomicStore(&counters[1], 0);
    }
}

@compute @workgroup_size(64)
fn cs_init(@builtin(global_invocation_id) g: vec3u) {
    if (f32(g.x) >= sim.params.z) {
        return;
    }
    let n = atomicSub(&counters[0], 1);
    if (n <= 0) {
        atomicAdd(&counters[0], 1);
        return;
    }
    let index = dead[n - 1];
    var p: Particle;
    p.id = sim.seeds.y + g.x;
    p.seed = vfx_hash(p.id ^ vfx_hash(sim.seeds.x));
    p.alive = 1u;
    p.age = 0.0;
    p.lifetime = 1.0;
    p.color = vec3f(1.0);
    p.alpha = 1.0;
    p.size = 0.1;
    p.scale_y = 1.0;
    p.mass = 1.0;
    vfx_init(&p);
    if (VFX_LOCAL == 0u) {
        p.position = (sim.object_to_world * vec4f(p.position, 1.0)).xyz;
        p.velocity = (sim.object_to_world * vec4f(p.velocity, 0.0)).xyz;
    }
    particles[index] = p;
    atomicAdd(&counters[1], 1);
}

@compute @workgroup_size(64)
fn cs_update(@builtin(global_invocation_id) g: vec3u) {
    if (g.x >= u32(sim.params.w)) {
        return;
    }
    var p = particles[g.x];
    if (p.alive == 0u) {
        return;
    }
    p.age += vfx_dt();
    vfx_update(&p);
    p.position += p.velocity * vfx_dt();
    if (p.age >= p.lifetime) {
        p.alive = 0u;
        let n = atomicAdd(&counters[0], 1);
        dead[n] = g.x;
        atomicSub(&counters[1], 1);
    }
    particles[g.x] = p;
}
";

const RENDER_TEMPLATE: &str = "
@group(1) @binding(0) var<storage, read> particles: array<Particle>;
@group(1) @binding(1) var<uniform> sim: Sim;
@group(1) @binding(2) var<uniform> props: array<vec4f, 64>;
@group(1) @binding(3) var<storage, read> luts: array<vec4f>;
@group(1) @binding(4) var vfx_tex: texture_2d<f32>;
@group(1) @binding(5) var vfx_samp: sampler;

fn vfx_view_matrix() -> mat4x4f {
    return frame.view;
}

fn vfx_camera_pos() -> vec3f {
    return frame.camera_pos.xyz;
}

//#HOOKS

struct VOut {
    @builtin(position) clip: vec4f,
    @location(0) uv: vec2f,
    @location(1) color: vec4f,
    @location(2) world_pos: vec3f,
};

@vertex
fn vs_main(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VOut {
    var o: VOut;
    var p = particles[ii];
    if (p.alive == 0u) {
        o.clip = vec4f(2.0, 2.0, 2.0, 1.0);
        return o;
    }
    vfx_output(&p);
    var corners = array<vec2f, 6>(vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0), vec2f(-1.0, -1.0), vec2f(1.0, 1.0), vec2f(-1.0, 1.0));
    let c = corners[vi];
    var pos = p.position;
    var vel = p.velocity;
    if (VFX_LOCAL == 1u) {
        pos = (sim.object_to_world * vec4f(pos, 1.0)).xyz;
        vel = (sim.object_to_world * vec4f(vel, 0.0)).xyz;
    }
    // Unity's angle is in degrees, around the facing axis.
    let a = radians(p.angle);
    let r = vec2f(c.x * cos(a) - c.y * sin(a), c.x * sin(a) + c.y * cos(a)) * vec2f(1.0, p.scale_y);
    var right = vec3f(frame.view[0].x, frame.view[1].x, frame.view[2].x);
    var up = vec3f(frame.view[0].y, frame.view[1].y, frame.view[2].y);
    if (VFX_ORIENT == 1u && dot(vel, vel) > 1e-8) {
        // Along Velocity: the quad's up axis follows the motion, facing the camera.
        up = normalize(vel);
        let to_cam = normalize(frame.camera_pos.xyz - pos);
        let side = cross(up, to_cam);
        if (dot(side, side) > 1e-8) {
            right = normalize(side);
        }
    }
    let world = pos + (right * r.x + up * r.y) * p.size * 0.5;
    o.clip = frame.view_proj * vec4f(world, 1.0);
    var uv = c * 0.5 + 0.5;
    if (VFX_FLIPBOOK.x > 0u) {
        let n = max(VFX_FLIPBOOK.x * VFX_FLIPBOOK.y, 1u);
        let f = u32(max(p.tex_index, 0.0)) % n;
        let cols = max(VFX_FLIPBOOK.x, 1u);
        let cell = vec2f(f32(f % cols), f32(max(VFX_FLIPBOOK.y, 1u) - 1u - f / cols));
        uv = (uv + cell) / vec2f(max(VFX_FLIPBOOK, vec2u(1u)));
    }
    o.uv = uv;
    o.color = vec4f(p.color, p.alpha);
    o.world_pos = world;
    return o;
}

@fragment
fn fs_main(in: VOut) -> @location(0) vec4f {
    var t = textureSample(vfx_tex, vfx_samp, vec2f(in.uv.x, 1.0 - in.uv.y));
    if (VFX_DOT == 1u) {
        // Unity's Default-Particle: a soft round dot.
        let d = length(in.uv * 2.0 - 1.0);
        t = vec4f(1.0, 1.0, 1.0, 1.0 - smoothstep(0.3, 1.0, d));
    }
    var c = t * in.color;
    if (VFX_BLEND == 2u) {
        if (c.a < 0.5) {
            discard;
        }
        c.a = 1.0;
    }
    return vec4f(apply_fog(c.rgb, in.world_pos), c.a);
}
";

/// Constants a program's hooks are compiled with.
fn constants(d: &crate::frame::VfxProgram) -> String {
    format!(
        "const VFX_LOCAL: u32 = {}u;\nconst VFX_DOT: u32 = {}u;\nconst VFX_ORIENT: u32 = {}u;\nconst VFX_BLEND: u32 = {}u;\nconst VFX_FLIPBOOK: vec2u = vec2u({}u, {}u);\n",
        d.local_space as u32,
        d.soft_dot as u32,
        match d.orient {
            VfxOrient::FaceCamera => 0,
            VfxOrient::AlongVelocity => 1,
        },
        match d.blend {
            VfxBlend::Alpha => 0,
            VfxBlend::Additive => 1,
            VfxBlend::Opaque => 2,
        },
        d.flipbook[0],
        d.flipbook[1],
    )
}

/// The compute shader of a program (without the common header).
pub fn compute_source(p: &crate::frame::VfxProgram) -> String {
    format!(
        "{}{PARTICLE_DECLS}{}",
        constants(p),
        COMPUTE_TEMPLATE.replace("//#HOOKS", &p.hooks)
    )
}

/// The render shader of a program (without the common header).
pub fn render_source(p: &crate::frame::VfxProgram) -> String {
    format!(
        "{}{PARTICLE_DECLS}{}",
        constants(p),
        RENDER_TEMPLATE.replace("//#HOOKS", &p.hooks)
    )
}

/// Checks a program's hooks in both shaders (VFX Graph compile errors).
pub fn validate_program(p: &crate::frame::VfxProgram) -> Result<(), String> {
    validate_wgsl(&compute_source(p)).map_err(|e| format!("simulation: {e}"))?;
    let common = include_str!("shaders/common.wgsl");
    validate_wgsl(&format!("{common}\n{}", render_source(p))).map_err(|e| format!("output: {e}"))
}

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct SimUniform {
    object_to_world: [[f32; 4]; 4],
    world_to_object: [[f32; 4]; 4],
    params: [f32; 4],
    seeds: [u32; 4],
}

struct Program {
    reset: wgpu::ComputePipeline,
    init: wgpu::ComputePipeline,
    update: wgpu::ComputePipeline,
    render: wgpu::ShaderModule,
    pipelines: HashMap<u32, wgpu::RenderPipeline>,
    blend: VfxBlend,
}

struct Instance {
    program: u64,
    capacity: u32,
    sim: wgpu::Buffer,
    props: wgpu::Buffer,
    compute_group: wgpu::BindGroup,
    particles: wgpu::Buffer,
    luts: wgpu::Buffer,
    render_groups: HashMap<Option<AssetId>, wgpu::BindGroup>,
    last_frame: Option<u64>,
    last_seen: u64,
    reset: bool,
    spawned: u32,
}

pub struct VfxGpu {
    compute_layout: wgpu::BindGroupLayout,
    render_layout: wgpu::BindGroupLayout,
    compute_pl: wgpu::PipelineLayout,
    render_pl: wgpu::PipelineLayout,
    sampler: wgpu::Sampler,
    white: wgpu::TextureView,
    programs: HashMap<u64, Option<Program>>,
    instances: HashMap<u64, Instance>,
    frames: u64,
}

fn storage(binding: u32, read_only: bool, vis: wgpu::ShaderStages) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: vis,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

fn uniform(binding: u32, vis: wgpu::ShaderStages) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: vis,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Uniform,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

impl VfxGpu {
    pub fn new(
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        frame_layout: &wgpu::BindGroupLayout,
    ) -> Self {
        let c = wgpu::ShaderStages::COMPUTE;
        let compute_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("vfx compute layout"),
            entries: &[
                storage(0, false, c),
                storage(1, false, c),
                storage(2, false, c),
                uniform(3, c),
                uniform(4, c),
                storage(5, true, c),
            ],
        });
        let v = wgpu::ShaderStages::VERTEX;
        let vf = wgpu::ShaderStages::VERTEX_FRAGMENT;
        let render_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("vfx render layout"),
            entries: &[
                storage(0, true, v),
                uniform(1, vf),
                uniform(2, vf),
                storage(3, true, vf),
                wgpu::BindGroupLayoutEntry {
                    binding: 4,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 5,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
        let compute_pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("vfx compute"),
            bind_group_layouts: &[Some(&compute_layout)],
            immediate_size: 0,
        });
        let render_pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("vfx render"),
            bind_group_layouts: &[Some(frame_layout), Some(&render_layout)],
            immediate_size: 0,
        });
        let sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("vfx sampler"),
            mag_filter: wgpu::FilterMode::Linear,
            min_filter: wgpu::FilterMode::Linear,
            mipmap_filter: wgpu::MipmapFilterMode::Linear,
            ..Default::default()
        });
        let white = device
            .create_texture_with_data(
                queue,
                &wgpu::TextureDescriptor {
                    label: Some("vfx white"),
                    size: wgpu::Extent3d {
                        width: 1,
                        height: 1,
                        depth_or_array_layers: 1,
                    },
                    mip_level_count: 1,
                    sample_count: 1,
                    dimension: wgpu::TextureDimension::D2,
                    format: wgpu::TextureFormat::Rgba8UnormSrgb,
                    usage: wgpu::TextureUsages::TEXTURE_BINDING,
                    view_formats: &[],
                },
                wgpu::util::TextureDataOrder::LayerMajor,
                &[255; 4],
            )
            .create_view(&Default::default());
        Self {
            compute_layout,
            render_layout,
            compute_pl,
            render_pl,
            sampler,
            white,
            programs: HashMap::new(),
            instances: HashMap::new(),
            frames: 0,
        }
    }

    fn program(&mut self, device: &wgpu::Device, d: &VfxDraw) -> bool {
        let p = &d.program;
        if let Some(entry) = self.programs.get(&p.hash) {
            return entry.is_some();
        }
        if let Err(e) = validate_program(p) {
            oxide_core::debug_log_error!("Visual Effect {}: {e}", p.name);
            self.programs.insert(p.hash, None);
            return false;
        }
        let cm = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("vfx simulation"),
            source: wgpu::ShaderSource::Wgsl(compute_source(p).into()),
        });
        let common = include_str!("shaders/common.wgsl");
        let render = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("vfx output"),
            source: wgpu::ShaderSource::Wgsl(format!("{common}\n{}", render_source(p)).into()),
        });
        let cp = |entry: &str| {
            device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
                label: Some(entry),
                layout: Some(&self.compute_pl),
                module: &cm,
                entry_point: Some(entry),
                compilation_options: Default::default(),
                cache: None,
            })
        };
        self.programs.insert(
            p.hash,
            Some(Program {
                reset: cp("cs_reset"),
                init: cp("cs_init"),
                update: cp("cs_update"),
                render,
                pipelines: HashMap::new(),
                blend: p.blend,
            }),
        );
        true
    }

    fn instance(&mut self, device: &wgpu::Device, d: &VfxDraw) {
        let cap = d.program.capacity.max(1);
        if self
            .instances
            .get(&d.key)
            .is_some_and(|i| i.program == d.program.hash && i.capacity == cap)
        {
            return;
        }
        let buf = |label: &str, size: u64, usage: wgpu::BufferUsages| {
            device.create_buffer(&wgpu::BufferDescriptor {
                label: Some(label),
                size,
                usage,
                mapped_at_creation: false,
            })
        };
        let st = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST;
        let particles = buf("vfx particles", PARTICLE_SIZE * cap as u64, st);
        let dead = buf("vfx dead list", 4 * cap as u64, st);
        let counters = buf("vfx counters", 16, st);
        let un = wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST;
        let sim = buf("vfx sim", std::mem::size_of::<SimUniform>() as u64, un);
        let props = buf("vfx properties", 16 * PROPERTY_SLOTS as u64, un);
        let mut lut_data = d.program.luts.clone();
        if lut_data.is_empty() {
            lut_data.push([0.0; 4]);
        }
        let luts = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("vfx curves"),
            contents: bytemuck::cast_slice(&lut_data),
            usage: wgpu::BufferUsages::STORAGE,
        });
        let compute_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("vfx compute"),
            layout: &self.compute_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: particles.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: dead.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: counters.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: sim.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 4,
                    resource: props.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 5,
                    resource: luts.as_entire_binding(),
                },
            ],
        });
        self.instances.insert(
            d.key,
            Instance {
                program: d.program.hash,
                capacity: cap,
                sim,
                props,
                compute_group,
                particles,
                luts,
                render_groups: HashMap::new(),
                last_frame: None,
                last_seen: self.frames,
                reset: true,
                spawned: 0,
            },
        );
    }

    /// Steps every system once per effect update (the Scene and Game views render the same
    /// frame without simulating twice) and prepares their draws.
    #[allow(clippy::too_many_arguments)]
    pub fn simulate(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        gpu_assets: &mut GpuAssets,
        assets: &AssetServer,
        frame: &RenderFrame,
        samples: u32,
    ) {
        self.frames += 1;
        for d in &frame.vfx {
            if !self.program(device, d) {
                continue;
            }
            self.instance(device, d);
            self.pipeline(device, d.program.hash, samples);
            // Render bind group for the texture.
            let view_tex = d
                .texture
                .and_then(|id| gpu_assets.texture_view(device, queue, assets, id).cloned());
            let frames = self.frames;
            let Some(inst) = self.instances.get_mut(&d.key) else {
                continue;
            };
            inst.last_seen = frames;
            if !inst.render_groups.contains_key(&d.texture) {
                let view = view_tex.as_ref().unwrap_or(&self.white);
                let g = device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("vfx render"),
                    layout: &self.render_layout,
                    entries: &[
                        wgpu::BindGroupEntry {
                            binding: 0,
                            resource: inst.particles.as_entire_binding(),
                        },
                        wgpu::BindGroupEntry {
                            binding: 1,
                            resource: inst.sim.as_entire_binding(),
                        },
                        wgpu::BindGroupEntry {
                            binding: 2,
                            resource: inst.props.as_entire_binding(),
                        },
                        wgpu::BindGroupEntry {
                            binding: 3,
                            resource: inst.luts.as_entire_binding(),
                        },
                        wgpu::BindGroupEntry {
                            binding: 4,
                            resource: wgpu::BindingResource::TextureView(view),
                        },
                        wgpu::BindGroupEntry {
                            binding: 5,
                            resource: wgpu::BindingResource::Sampler(&self.sampler),
                        },
                    ],
                });
                inst.render_groups.insert(d.texture, g);
            }
            let step = d.simulate && inst.last_frame != Some(d.step);
            let spawn = if step { d.spawn.min(inst.capacity) } else { 0 };
            let m = d.object_to_world;
            let sim = SimUniform {
                object_to_world: m.to_cols_array_2d(),
                world_to_object: m.inverse().to_cols_array_2d(),
                params: [
                    d.time,
                    if step { d.dt } else { 0.0 },
                    spawn as f32,
                    inst.capacity as f32,
                ],
                seeds: [
                    d.seed ^ (d.step as u32).wrapping_mul(2654435761),
                    inst.spawned,
                    0,
                    0,
                ],
            };
            queue.write_buffer(&inst.sim, 0, bytemuck::bytes_of(&sim));
            let mut props = [[0.0f32; 4]; PROPERTY_SLOTS];
            for (k, v) in d.properties.iter().take(PROPERTY_SLOTS).enumerate() {
                props[k] = *v;
            }
            queue.write_buffer(&inst.props, 0, bytemuck::cast_slice(&props));
            if !step {
                continue;
            }
            inst.last_frame = Some(d.step);
            let reset = inst.reset || d.reset;
            inst.reset = false;
            if reset {
                inst.spawned = 0;
            }
            inst.spawned = inst.spawned.wrapping_add(spawn);
            let Some(Some(prog)) = self.programs.get(&d.program.hash) else {
                continue;
            };
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("vfx simulation"),
                timestamp_writes: None,
            });
            pass.set_bind_group(0, &inst.compute_group, &[]);
            let groups = inst.capacity.div_ceil(WORKGROUP);
            if reset {
                pass.set_pipeline(&prog.reset);
                pass.dispatch_workgroups(groups, 1, 1);
            }
            if spawn > 0 {
                pass.set_pipeline(&prog.init);
                pass.dispatch_workgroups(spawn.div_ceil(WORKGROUP), 1, 1);
            }
            pass.set_pipeline(&prog.update);
            pass.dispatch_workgroups(groups, 1, 1);
        }
        // Drop systems that stopped being drawn.
        let frames = self.frames;
        self.instances.retain(|_, i| frames - i.last_seen < 300);
    }

    fn pipeline(&mut self, device: &wgpu::Device, program: u64, samples: u32) {
        let Some(Some(p)) = self.programs.get_mut(&program) else {
            return;
        };
        if p.pipelines.contains_key(&samples) {
            return;
        }
        let blend = match p.blend {
            VfxBlend::Alpha => Some(wgpu::BlendState::ALPHA_BLENDING),
            VfxBlend::Additive => Some(wgpu::BlendState {
                color: wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::SrcAlpha,
                    dst_factor: wgpu::BlendFactor::One,
                    operation: wgpu::BlendOperation::Add,
                },
                alpha: wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::Zero,
                    dst_factor: wgpu::BlendFactor::One,
                    operation: wgpu::BlendOperation::Add,
                },
            }),
            VfxBlend::Opaque => None,
        };
        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("vfx output"),
            layout: Some(&self.render_pl),
            vertex: wgpu::VertexState {
                module: &p.render,
                entry_point: Some("vs_main"),
                compilation_options: Default::default(),
                buffers: &[],
            },
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: Some(wgpu::DepthStencilState {
                format: DEPTH_FORMAT,
                depth_write_enabled: Some(p.blend == VfxBlend::Opaque),
                depth_compare: Some(wgpu::CompareFunction::GreaterEqual),
                stencil: Default::default(),
                bias: Default::default(),
            }),
            multisample: wgpu::MultisampleState {
                count: samples,
                ..Default::default()
            },
            fragment: Some(wgpu::FragmentState {
                module: &p.render,
                entry_point: Some("fs_main"),
                compilation_options: Default::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: HDR_FORMAT,
                    blend,
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            multiview_mask: None,
            cache: None,
        });
        p.pipelines.insert(samples, pipeline);
    }

    /// Draws every system (after the transparent objects). Returns the draw calls.
    pub fn draw(&self, pass: &mut wgpu::RenderPass<'_>, frame: &RenderFrame, samples: u32) -> u32 {
        let mut calls = 0;
        for d in frame.vfx.iter().filter(|d| d.visible) {
            let (Some(Some(p)), Some(inst)) = (
                self.programs.get(&d.program.hash),
                self.instances.get(&d.key),
            ) else {
                continue;
            };
            let (Some(pipeline), Some(group)) = (
                p.pipelines.get(&samples),
                inst.render_groups.get(&d.texture),
            ) else {
                continue;
            };
            pass.set_pipeline(pipeline);
            pass.set_bind_group(1, group, &[]);
            pass.draw(0..6, 0..inst.capacity);
            calls += 1;
        }
        calls
    }
}
